import React, { useState, useEffect } from "react";
import Chat from './components/Chat';

function App() {
  const [personality, setPersonality] = useState('T');
  const [gender, setGender] = useState('M');
  const [isSettingsVisible, setIsSettingsVisible] = useState(true);

  useEffect(() => {
    // 로컬 저장소에서 값 불러오기
    const savedPersonality = localStorage.getItem('personality') || 'T';
    const savedGender = localStorage.getItem('gender') || 'M';

    setPersonality(savedPersonality);
    setGender(savedGender);
  }, []);

  const saveSettings = async () => {
    // 로컬 저장소에 설정 값 저장
    localStorage.setItem('personality', personality);
    localStorage.setItem('gender', gender);

    try {
      await fetch(`${process.env.REACT_APP_API_URL}/settings`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ personality, gender }),
      });

      setIsSettingsVisible(false);  // 설정 페이지 숨기기
    } catch (error) {
      console.error('설정 업데이트 오류:', error);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>챗봇과 대화하기</h1>
        {isSettingsVisible ? (
          <div>
            <h2>챗봇 설정</h2>
            <label>
              성격:
              <select value={personality} onChange={(e) => setPersonality(e.target.value)}>
                <option value="T">현실적</option>
                <option value="F">감정적</option>
              </select>
            </label>
            <br />
            <label>
              성별:
              <select value={gender} onChange={(e) => setGender(e.target.value)}>
                <option value="M">남성</option>
                <option value="W">여성</option>
              </select>
            </label>
            <br />
            <button onClick={saveSettings}>채팅 시작</button>
          </div>
        ) : (
          <Chat personality={personality} gender={gender} />
        )}
      </header>
    </div>
  );
}

export default App;
